grep -rl "fallback_risk_pct" logs 2>/dev/null | head -3; f=$(grep -rl "fallback_risk_pct" logs 2>/dev/null | head -200); [ -n "$f" ] && python3 -I -c '
import json,sys,re
seen={}
for p in sys.argv[1:]:
    try: d=json.load(open(p))
    except Exception: continue
    def walk(o):
        if isinstance(o,dict):
            if "category_goal" in o and "fallback_risk_pct" in o:
                seen.setdefault(o.get("category_goal"),set()).add((o.get("fallback_risk_pct"),o.get("sustainable_margin_pct")))
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(d)
for k,v in seen.items(): print(k,sorted(v,key=str))
' $f
